import os
import ast

keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

def inspect_file(filepath):
    with open(filepath, 'r') as f:
        content = f.read()

    try:
        tree = ast.parse(content, filename=filepath)
    except SyntaxError:
        print(f"Syntax error in {filepath}")
        return

    # Let's find legacy_auth calls and find their containing functions.
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            # Check if legacy_auth is called inside this function.
            has_legacy_auth = False
            for child in ast.walk(node):
                if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                    has_legacy_auth = True
                    break

            if has_legacy_auth:
                # Let's get the source code of this function or look at its contents.
                func_code = ast.get_source_segment(content, node) or ""
                # Check for keywords
                matched_keywords = [kw for kw in keywords if kw in func_code]
                # Also check the file path itself, just in case
                matched_path_kw = [kw for kw in keywords if kw in filepath]
                print(f"File: {filepath}, Function: {node.name}")
                print(f"  Matched body keywords: {matched_keywords}")
                print(f"  Matched path keywords: {matched_path_kw}")
                print(f"  First few lines:\n" + "\n".join("    " + line for line in func_code.splitlines()[:5]))

for root, dirs, files in os.walk('app'):
    for file in files:
        if file.endswith('.py') and file != 'auth.py':
            inspect_file(os.path.join(root, file))

