import os
import re

keywords = ["create", "update", "delete", "save", "write", "post", "put", "patch"]

for root, dirs, files in os.walk('app'):
    for file in files:
        if file.endswith('.py') and file != 'auth.py':
            filepath = os.path.join(root, file)
            with open(filepath, 'r') as f:
                content = f.read()
            for kw in keywords:
                # Find all occurrences of kw (case-insensitive)
                matches = re.findall(kw, content, re.IGNORECASE)
                if matches:
                    print(f"File: {filepath} has word {kw} (matches count: {len(matches)})")
